// narrative.mjs —— 叙述校验器。
// AI 提交的「这轮干成了什么」叙述段必须过这一关才许进草稿。
// 两条规则，来自设计文档「嘴不许碰账」与「白话=白话因果×具名锚点」：
// ① 禁带账目数字：叙述里同时出现记账字眼（$、¥、%、成本、花费）和阿拉伯数字就拒收——
//    钱和百分比一律由账本现算、脚本来填，AI 的嘴不许碰账。
// ② 必须具名锚点：叙述至少要点名一个「谁 / 什么文件 / 什么产出」，不许全是空话。
//    宽松规则（有意写死，宁可放过不可错杀）：全文长度 ≥ 20，且含中文顿号（、）
//    或成对引号（「」『』“”）包裹的名词，就算有锚点。

// 记账字眼：货币符号、百分号、以及「成本」「花费」两个词。
const LEDGER_WORDS = /[$¥￥%％]|成本|花费/;
// 阿拉伯数字（含全角）。中文数字（两处、三篇）不算账目数字，正常叙述照常用。
const DIGITS = /[0-9０-９]/;
// 成对引号包裹的内容，视作点名了具体的人或物。
const QUOTED = /[「『“].+?[」』”]/;

// 机器话术黑名单（2026-07-17，老板反馈「本轮工作内容和下轮工作计划写的都不是 human-readable
// 的东西」）：汇报的三栏是**老板唯一会读的东西**，可 decisions/next_plan 此前压根没有任何风格
// 约定、也没有校验——于是内部协议原样漏进汇报（真实案例：下轮计划写成「下一轮预检会给出
// action=execute、sprint=M1-S3」，本轮工作内容里塞着 npx vitest run、a-e84a752b、3fr/2fr）。
//
// 这里只拦「铁定是给机器看、老板绝不可能读的记号」——命令行参数、内部字段赋值、shell 命令、
// 环境/运行编号。刻意不拦文件名、里程碑代号（M1-S2 是老板自己在里程碑树上看的词）、专有名词：
// 「文风够不够白话」不是正则判得了的事，那一关靠 skills/opc-tick 里的栏目定义与正反例去立规矩。
// 沿用本文件既有的风险姿态——**宁可放过不可错杀**：这道闸挡下就等于这一轮收不了尾（tick-end
// 会喊停、锁不放），错杀一次的代价远大于漏过一句难读的话。
const MACHINE_TOKENS = [
  { re: /--(json|gen|actor|id|cwd)\b/, what: '命令行参数' },
  { re: /\b(action|sprint|status|gen|run_id|agent_id|project_id)\s*=/, what: '内部字段赋值' },
  { re: /\b(npm run|npx|kubectl|vitest)\b/, what: 'shell 命令' },
  { re: /\ba-[0-9a-f]{8}\b/, what: '环境编号' },
  { re: /\br-\d{10,}/, what: '运行编号' }
];

/**
 * 校验一段「写给老板看」的话（叙述 / 关键决策 / 下轮计划共用）。
 * 合格返回 {ok:true}；不合格返回 {ok:false, reason:白话原因}——原因要能直接告诉写的人怎么改。
 */
export function checkPlainLanguage(text, label = '这段话') {
  if (typeof text !== 'string') return { ok: true }; // 类型的事由各自的 schema 管，这里只管文风
  for (const { re, what } of MACHINE_TOKENS) {
    const hit = text.match(re);
    if (hit) {
      return {
        ok: false,
        reason: `${label}里出现了「${hit[0]}」这种${what}——汇报是写给老板看的，他不读命令、编号和内部字段。`
          + `请换成大白话说清「干了什么、为什么、结果怎样」（技术细节留给收据和产出清单，不必写进汇报）`
      };
    }
  }
  return { ok: true };
}

// 校验一段叙述。合格返回 {ok:true}；不合格返回 {ok:false, reason:白话原因}。
export function checkNarrative(text) {
  if (typeof text !== 'string' || text.trim() === '') {
    return { ok: false, reason: '叙述不能为空' };
  }
  if (DIGITS.test(text) && LEDGER_WORDS.test(text)) {
    return {
      ok: false,
      reason: '叙述里不许出现账目数字（成本、花费、百分比这类），钱的事由账本现算、脚本来填'
    };
  }
  const hasAnchor = text.length >= 20 && (text.includes('、') || QUOTED.test(text));
  if (!hasAnchor) {
    return {
      ok: false,
      reason: '叙述必须具名：至少点名一个「谁 / 什么东西 / 什么产出」（用引号或顿号列出具体名字），并且别少于二十个字'
    };
  }
  return checkPlainLanguage(text, '叙述'); // 具名之外还得是人话，见 checkPlainLanguage 头注
}

/** 一段话的长度上限：超过就必须拆条/分段，不许糊成一堵墙。 */
export const PARAGRAPH_MAX = 150;

/**
 * 「别写一长段」的机器闸（2026-07-17，老板第二次投诉同一件事：请示「没有任何的格式感，
 * 我都不懂他想让我干什么」）。
 *
 * 上一版的修法是「加 background/impact 两个结构化字段，指望 AI 分格写」——失败了：AI 照样
 * 把同一堵墙原样塞进 background（真实案例：Aside 的 A-0004 背景是 250 字不换行的一整段，
 * 里头还嵌着 e2e:followup、success.json、a-14e2be79、python3 -m http.server $PORT）。
 * 加字段不等于加结构：**字段能装下墙，墙就还在**。所以这一版改成量得出来的闸——
 * 单段超过 PARAGRAPH_MAX 字就打回，逼它拆条。
 *
 * 按空行/换行切段后逐段量：短段随便写；长内容必须自己拆成条目或分段。这是「条理清晰」
 * 唯一量得出来的部分（写得好不好仍靠栏目定义与正反例，正则管不了）。
 */
export function checkNotAWall(text, label = '这段话') {
  if (typeof text !== 'string') return { ok: true };
  for (const para of text.split(/\n+/)) {
    const line = para.trim();
    // 列表项/小标题这类本就是「拆过的」，即使长也不算墙——拆条的目的已经达到了
    if (/^\s*([-*+•]|\d+[.、)]|#{1,6}\s)/.test(line)) continue;
    if (line.length > PARAGRAPH_MAX) {
      return {
        ok: false,
        reason: `${label}里有一段 ${line.length} 字的话没断开（上限 ${PARAGRAPH_MAX} 字）——老板要的是「条理清晰、不要一长段话」。`
          + `请拆成几条（每条一句话，用 - 开头），把「要老板做什么」放最前面，背景和影响各归各条`
      };
    }
  }
  return { ok: true };
}

/**
 * 校验汇报里那两栏纯散文（关键决策逐条 / 下轮计划）——老板点名说这两栏「不是 human-readable
 * 的东西」，它们此前一道闸都没有。产出清单（outputs）不在此列：那栏本就是给人对照的文件/产出
 * 名单，路径写在那儿是本分。
 * @returns {{ok: true} | {ok: false, reason: string}}
 */
export function checkReportProse({ decisions, next_plan: nextPlan } = {}) {
  if (Array.isArray(decisions)) {
    for (const item of decisions) {
      const check = checkPlainLanguage(item, '关键决策');
      if (!check.ok) return check;
    }
  }
  return checkPlainLanguage(nextPlan, '下轮计划');
}

